package com.agacostays.payroll.service.impl; import com.agacostays.payroll.dto.request.*; import com.agacostays.payroll.dto.response.*; import com.agacostays.payroll.entity.*; import com.agacostays.payroll.enums.*; import com.agacostays.payroll.exception.*; import com.agacostays.payroll.mapper.*; import com.agacostays.payroll.repository.*; import com.agacostays.payroll.service.*; import org.springframework.beans.factory.annotation.Value; import org.springframework.stereotype.Service; import jakarta.transaction.Transactional; import java.math.*; import java.time.LocalDate;
@Service public class SalaryStructureServiceImpl implements SalaryStructureService{final SalaryStructureRepository repo;final SalaryStructureMapper mapper;final String currency;public SalaryStructureServiceImpl(SalaryStructureRepository r,SalaryStructureMapper m,@Value("${payroll.currency}")String c){repo=r;mapper=m;currency=c;}public SalaryStructureResponse create(SalaryStructureRequest r,Long actor){BigDecimal b=n(r.basicSalary()),h=n(r.hra()),a=n(r.allowances()),d=n(r.deductions());SalaryStructure x=SalaryStructure.builder().roleId(r.roleId()).roleName(r.roleName()).basicSalary(b).hra(h).allowances(a).deductions(d).monthlyGrossSalary(b.add(h).add(a)).monthlyNetSalary(b.add(h).add(a).subtract(d).max(BigDecimal.ZERO)).currency(r.currency()==null?currency:r.currency()).effectiveFrom(r.effectiveFrom()==null?LocalDate.now():r.effectiveFrom()).status(SalaryStructureStatus.ACTIVE).createdBy(actor).build();return mapper.toResponse(repo.save(x));}public java.util.List<SalaryStructureResponse> list(){return repo.findByStatusOrderByRoleNameAsc(SalaryStructureStatus.ACTIVE).stream().map(mapper::toResponse).toList();}public SalaryStructureResponse byRole(String role){return repo.findByRoleNameIgnoreCaseAndStatus(role,SalaryStructureStatus.ACTIVE).stream().findFirst().map(mapper::toResponse).orElseThrow(()->new ResourceNotFoundException("Salary structure not found for role: "+role));}@Transactional public SalaryStructureResponse update(Long id,SalaryStructureRequest r,Long actor){SalaryStructure x=repo.findById(id).orElseThrow(()->new ResourceNotFoundException("Salary structure not found: "+id));x.setRoleId(r.roleId());x.setRoleName(r.roleName());x.setBasicSalary(n(r.basicSalary()));x.setHra(n(r.hra()));x.setAllowances(n(r.allowances()));x.setDeductions(n(r.deductions()));x.setMonthlyGrossSalary(x.getBasicSalary().add(x.getHra()).add(x.getAllowances()));x.setMonthlyNetSalary(x.getMonthlyGrossSalary().subtract(x.getDeductions()).max(BigDecimal.ZERO));if(r.effectiveFrom()!=null)x.setEffectiveFrom(r.effectiveFrom());if(r.currency()!=null)x.setCurrency(r.currency());return mapper.toResponse(repo.save(x));}@Transactional public void deactivate(Long id){SalaryStructure x=repo.findById(id).orElseThrow(()->new ResourceNotFoundException("Salary structure not found: "+id));x.setStatus(SalaryStructureStatus.INACTIVE);repo.save(x);}private BigDecimal n(BigDecimal x){return x==null?BigDecimal.ZERO:x;}}
